def build_test():
    selected = []
    for topic, count in TEST_WEIGHTS.items():
        pool = [q for q in QUESTION_BANK if q["topic"] == topic]
        selected.extend(random.sample(pool, count))
    random.shuffle(selected)
    return [q["id"] for q in selected]

def quiz_keyboard(index, q, order):
    letters = ["А","Б","В","Г"]
    displayed = [q["options"][original_index] for original_index in order]
    return inline([
        [{
            "text": f"{letters[i]}. {opt}",
            "callback_data": f"quiz:{index}:{i}"
        }]
        for i, opt in enumerate(displayed)
    ])

def start_quiz(tg_id, identity, mode):
    qids = build_test()
    option_orders = {}

    # Для кожного питання порядок варіантів формується окремо.
    # В БД зберігаємо порядок оригінальних індексів, тому правильність
    # не залежить від того, на якій кнопці опинилася правильна відповідь.
    for qid in qids:
        order = list(range(len(QUESTION_BY_ID[qid]["options"])))
        random.shuffle(order)
        option_orders[qid] = order

    payload = {
        "mode": mode,
        "identity": identity,
        "question_ids": qids,
        "option_orders": option_orders,
        "current": 0,
        "correct": 0,
        "answers": [],
        "topic_stats": {
            topic: {"correct":0,"total":0}
            for topic in TEST_WEIGHTS
        },
        "started_at": utc_now_iso()
    }
    set_state(tg_id, "quiz", payload)

    send_message(
        tg_id,
        "📝 <b>Перевірка знань</b>\n\n"
        f"👤 {escape(identity['full_name'])}\n"
        f"🏢 {escape(identity['site'])}\n"
        f"💼 {escape(identity['position'])}\n\n"
        f"Питань: <b>{TEST_QUESTION_COUNT}</b>\n"
        f"Ціль: <b>{PASS_PERCENT}%</b>\n\n"
        "Варіанти відповідей перемішуються випадково.\n"
        "Після відповіді наступне питання відкривається автоматично."
    )
    send_quiz_question(tg_id, payload)

def send_quiz_question(tg_id, payload, edit_message_id=None):
    idx = payload["current"]
    if idx >= len(payload["question_ids"]):
        finish_quiz(tg_id, payload, edit_message_id)
        return

    qid = payload["question_ids"][idx]
    q = QUESTION_BY_ID[qid]
    order = payload["option_orders"][qid]

    text = (
        f"🎓 <b>Питання {idx+1}/{len(payload['question_ids'])}</b>\n"
        f"Тема: <b>{escape(q['topic'])}</b>\n\n"
        f"{escape(q['q'])}"
    )

    if edit_message_id:
        edit_message(
            tg_id,
            edit_message_id,
            text,
            quiz_keyboard(idx, q, order)
        )
    else:
        result = send_message(
            tg_id,
            text,
            quiz_keyboard(idx, q, order)
        )
        if result.get("ok"):
            payload["quiz_message_id"] = result["result"]["message_id"]
            set_state(tg_id, "quiz", payload)

def finish_quiz(tg_id, payload, message_id=None):
    total = len(payload["question_ids"])
    correct = payload["correct"]
    percent = round(correct * 100 / total) if total else 0
    passed = percent >= PASS_PERCENT
    identity = payload["identity"]

    weak = []
    topic_results = {}

    for topic, stats in payload["topic_stats"].items():
        pct = (
            round(stats["correct"] * 100 / stats["total"])
            if stats["total"] else 0
        )
        topic_results[topic] = {
            "correct": stats["correct"],
            "total": stats["total"],
            "percent": pct
        }
        if stats["total"] and pct < PASS_PERCENT:
            weak.append(topic)

    attempt = {
        "mode": payload["mode"],
        "site": identity["site"],
        "position": identity["position"],
        "staff_id": identity["staff_id"],
        "full_name": identity["full_name"],
        "total": total,
        "correct": correct,
        "percent": percent,
        "passed": passed,
        "weak_topics": weak,
        "topic_results": topic_results,
        "started_at": payload["started_at"]
    }

    save_training_attempt(tg_id, attempt)
    bind_profile(tg_id, identity)
    clear_state(tg_id)

    lines = [
        "🎓 <b>Тест завершено</b>",
        "",
        f"👤 {escape(identity['full_name'])}",
        f"🏢 {escape(identity['site'])}",
        f"💼 {escape(identity['position'])}",
        "",
        f"✅ Правильних: <b>{correct}/{total}</b>",
        f"📊 Результат: <b>{percent}%</b>",
        "",
        "✅ <b>Результат достатній</b>"
        if passed else
        "⚠️ <b>Потрібне повторне навчання</b>"
    ]

    if weak:
        lines += ["", "<b>Слабкі теми:</b>"]
        for topic in weak:
            lines.append(
                f"• {escape(topic)} — {topic_results[topic]['percent']}%"
            )

    attention_topics = weak[:3]
    if not attention_topics:
        ranked_topics = sorted(
            topic_results.items(),
            key=lambda item: (item[1]["percent"], item[0])
        )
        attention_topics = [name for name, stats in ranked_topics[:2]]

    attention_lines = [
        f"• {escape(TOPIC_ATTENTION.get(topic, topic))}"
        for topic in attention_topics
    ]

    lines += [
        "",
        "🔎 <b>На що звернути увагу:</b>",
        *attention_lines
    ]

    result_text = "\n".join(lines)

    if message_id:
        edit_message(
            tg_id,
            message_id,
            result_text,
            training_menu()
        )
    else:
        send_message(tg_id, result_text, training_menu())

    if tg_id != ADMIN_ID:
        send_message(
            ADMIN_ID,
            "🎓 <b>Новий результат</b>\n\n"
            f"👤 {escape(identity['full_name'])}\n"
            f"🏢 {escape(identity['site'])}\n"
            f"💼 {escape(identity['position'])}\n"
            f"📊 <b>{percent}%</b>\n\n"
            "🔎 <b>Звернути увагу:</b>\n"
            + "\n".join(attention_lines)
        )

def handle_quiz_callback(cq):
    tg_id = cq["from"]["id"]
    state, payload = get_state(tg_id)

    if state != "quiz":
        answer_callback(cq["id"], "Тест уже завершено.")
        return

    try:
        _, idx_s, displayed_option_s = cq["data"].split(":", 2)
        idx = int(idx_s)
        displayed_option = int(displayed_option_s)
    except Exception:
        answer_callback(cq["id"], "Некоректна відповідь.")
        return

    if idx != payload["current"]:
        answer_callback(cq["id"], "Відповідь уже врахована.")
        return

    qid = payload["question_ids"][payload["current"]]
    q = QUESTION_BY_ID[qid]
    order = payload["option_orders"][qid]

    if displayed_option < 0 or displayed_option >= len(order):
        answer_callback(cq["id"], "Некоректна відповідь.")
        return

    original_option = order[displayed_option]
    ok = original_option == q["correct"]

    payload["topic_stats"][q["topic"]]["total"] += 1

    if ok:
        payload["correct"] += 1
        payload["topic_stats"][q["topic"]]["correct"] += 1

    payload["answers"].append({
        "qid": q["id"],
        "displayed_selected": displayed_option,
        "original_selected": original_option,
        "correct_original": q["correct"],
        "ok": ok
    })
    payload["current"] += 1
    set_state(tg_id, "quiz", payload)

    if ok:
        answer_callback(cq["id"], "✅ Правильно")
    else:
        answer_callback(
            cq["id"],
            "❌ Правильна: " + q["options"][q["correct"]]
        )

    send_quiz_question(
        tg_id,
        payload,
        edit_message_id=cq["message"]["message_id"]
    )

# =========================================================
# OBJECT SEARCH
# =========================================================

ALIASES = {
    "ваги":"автоваг",
    "автовагова":"автоваг",
    "ворота":"ворота",
    "кода":"кода",
    "свс":"свс",
    "скуд":"скуд",
    "генератор":"генератор",
    "топкова":"топкова",
    "втл":"втл",
    "сервер":"сервер",
}

def normalize_search(text):
    text = (text or "").lower()
    text = text.replace("’", "'").replace("`", "'")
    text = re.sub(r"[^а-яіїєґa-z0-9№' -]+", " ", text)
    return re.sub(r"\s+", " ", text).strip()

def search_objects(query):
    q = normalize_search(query)
    if not q:
        return []

    variants = [q]
    for alias, target in ALIASES.items():
        if alias in q:
            variants.append(q.replace(alias, target))

    found = []

    for obj in OBJECTS_BILOVODY:
        hay = normalize_search(obj["name"])
        score = 0

        for variant in variants:
            if variant == hay:
                score = max(score, 100)
            elif variant in hay:
                score = max(score, 80)
            else:
                words = [w for w in variant.split() if len(w) >= 2]
                if words and all(w in hay for w in words):
                    score = max(score, 60)

        if score:
            found.append((score, obj))

    found.sort(key=lambda x: (-x[0], x[1]["name"]))
    return [x[1] for x in found[:8]]

def object_card(obj):
    seals = obj.get("seals")
    seals_text = (
        str(seals)
        if seals not in (None, "")
        else "не вказано / за категорією"
    )

    responsibles = obj.get("responsibles") or []
    resp_text = (
        "\n".join(f"• {escape(x)}" for x in responsibles[:6])
        or "• не вказано"
    )

    return (
        f"🏢 <b>{escape(obj['name'])}</b>\n"
        f"🔖 Пломб: <b>{escape(seals_text)}</b>\n"
        f"🛡 Тип: <b>{escape(str(obj.get('guard_type') or '—'))}</b>\n"
        f"👤 МВО / відповідальні:\n{resp_text}"
    )

