def admin_rating_text():
    latest = latest_attempts_by_identity()
    lines = ["🏆 <b>Рейтинг знань</b>", "", "<b>За дільницями:</b>"]
    site_rows = []
    for site in SITES:
        rows = [a for a in latest.values() if a.get("site") == site]
        if rows:
            site_rows.append((round(sum(a.get("percent",0) for a in rows)/len(rows)), site, len(rows)))
    for place, (avg, site, count) in enumerate(sorted(site_rows, key=lambda x:(-x[0],x[1])), 1):
        medal = "🥇" if place == 1 else "🥈" if place == 2 else "🥉" if place == 3 else f"{place}."
        lines.append(f"{medal} {escape(site)} — <b>{avg}%</b> ({count} ос.)")
    lines += ["", "<b>По кожному працівнику:</b>"]
    persons = sorted(latest.values(), key=lambda x:(x.get("site") or "", -(x.get("percent",0)), x.get("full_name") or ""))
    for a in persons[:60]:
        lines.append(f"• {escape(a.get('site') or '—')} · {escape(a.get('full_name') or '—')} — <b>{a.get('percent',0)}%</b>")
    if not persons:
        lines.append("📭 Результатів ще немає.")
    return "\n".join(lines)


