    group = payload.get("group") if payload.get("group") in ("ДЗ", "СБ") else "СБ"
    custom.setdefault(group, []).append({
        "full_name": payload.get("full_name"),
        "position": payload.get("position"),
        "phone": payload.get("phone"),
        "photo_file_id": photo_file_id,
        "created_at": utc_now_iso(),
    })
    data["leadership_custom"] = custom
    save_data(data)


