def admin_results_text():
    rows = all_attempts()
    if not rows:
        return "🎓 Результатів поки немає."

    grouped = {}
    for a in rows:
        site = a.get("site") or "Без дільниці"
        date = (a.get("finished_at") or "")[:10] or "Без дати"
        grouped.setdefault(site, {}).setdefault(date, []).append(a)

    lines = ["🎓 <b>Результати тестування</b>", ""]
    ordered_sites = [s for s in SITES if s in grouped] + [s for s in sorted(grouped) if s not in SITES]
    for site in ordered_sites:
        lines.append(f"🏢 <b>{escape(site)}</b>")
        for date in sorted(grouped[site], reverse=True):
            lines.append(f"📅 <b>{escape(date)}</b>")
            items = sorted(grouped[site][date], key=lambda a: (a.get("full_name") or "", -(a.get("percent") or 0)))
            for a in items:
                icon = "✅" if a.get("passed") else "⚠️"
                lines.append(
                    f"{icon} {escape(a.get('full_name') or '—')} — <b>{a.get('percent',0)}%</b> · "
                    f"{escape(a.get('position') or '—')}"
                )
            lines.append("")
        lines.append("")
    return "\n".join(lines)[:4000]

def admin_stats_text():
    data = load_data()

    active_users = [
        u for u in data["users"].values()
        if u.get("telegram_id") != ADMIN_ID
        and u.get("status") == "active"
    ]

    latest = latest_attempts_by_identity()
    completed = len(latest)

    avg = (
        round(
            sum(a.get("percent",0) for a in latest.values())
            / completed
        )
        if completed else 0
    )

    below = sum(
        1 for a in latest.values()
        if a.get("percent",0) < PASS_PERCENT
    )

    lines = [
        "📊 <b>Статистика знань</b>",
        "",
        f"👥 Активних Telegram-учасників: <b>{len(active_users)}</b>",
        f"👤 ПІБ із результатами: <b>{completed}</b>",
        f"📈 Середній результат: <b>{avg}%</b>",
        f"⚠️ Нижче {PASS_PERCENT}%: <b>{below}</b>",
        "",
        "<b>За дільницями:</b>"
    ]

    for site in SITES:
        rows = [a for a in latest.values() if a.get("site") == site]
        if rows:
            site_avg = round(
                sum(a.get("percent",0) for a in rows) / len(rows)
            )
            lines.append(
                f"• {site} — {len(rows)} ос., середній {site_avg}%"
            )
        else:
            lines.append(f"• {site} — тестів немає")

    lines += ["", "<b>За посадами:</b>"]

    for pos in POSITIONS:
        rows = [a for a in latest.values() if a.get("position") == pos]
        if rows:
            pos_avg = round(
                sum(a.get("percent",0) for a in rows) / len(rows)
            )
            lines.append(
                f"• {pos} — {len(rows)} ос., середній {pos_avg}%"
            )
        else:
            lines.append(f"• {pos} — тестів немає")

    return "\n".join(lines)

