def known_staff_for_site(site):
    people = {}
    data = load_data()

    for person in STAFF_DIRECTORY:
        if person.get("active") and person.get("site") == site:
            people[person["full_name"]] = {
                "name": person["full_name"],
                "telegram_id": None,
            }

    for tg_key, user in data["users"].items():
        if (
            user.get("status") == "active"
            and user.get("site") == site
            and user.get("full_name")
            and int(tg_key) != ADMIN_ID
        ):
            people[user["full_name"]] = {
                "name": user["full_name"],
                "telegram_id": int(tg_key),
            }

    return sorted(people.values(), key=lambda x: x["name"])


def shift_member_keyboard(site, post_no, exclude_name=None):
    required_position = "Старший охоронник" if int(post_no) == 1 else "Охоронник-пожежник"
    people = []
    for person in STAFF_DIRECTORY:
        if not person.get("active") or person.get("site") != site:
            continue
        if required_position not in (person.get("allowed_positions") or []):
            continue
        people.append({
            "name": person["full_name"],
            "telegram_id": find_linked_tg_id(person["full_name"], site),
        })
    people.sort(key=lambda x: x["name"])
    rows = [[{"text":p["name"],"callback_data":f"shift:member:{post_no}:{i}"}] for i,p in enumerate(people)]
    rows.append([{"text":"✍️ Ввести ПІБ вручну","callback_data":f"shift:manual:{post_no}"}])
    rows.append([{"text":"❌ Скасувати","callback_data":"menu:shift"}])
    return inline(rows), people


def master_keyboard(site):
    masters = MASTERS_BY_SITE.get(site, [])
    rows = [[{"text":name,"callback_data":f"shift:master:{i}"}] for i,name in enumerate(masters)]
    rows.append([{"text":"✍️ Ввести майстра вручну","callback_data":"shift:master:manual"}])
    rows.append([{"text":"❌ Скасувати","callback_data":"menu:shift"}])
    return inline(rows), masters


