def attention_for_topics(topic_results):
    weak = [
        topic for topic, stats in topic_results.items()
        if stats.get("total") and stats.get("percent", 0) < PASS_PERCENT
    ]

    if not weak:
        weak = [
            name for name, stats in sorted(
                topic_results.items(),
                key=lambda item: (item[1].get("percent",0), item[0])
            )[:2]
        ]

    return weak[:3]


