# TEXT MESSAGES
# =========================================================

def handle_start(msg):
    tg_id = msg["from"]["id"]
    username = msg["from"].get("username")

    if tg_id == ADMIN_ID:
        upsert_user(
            tg_id,
            username=(username or "").lstrip("@") or None,
            full_name="Адміністратор",
            role="admin",
            status="active"
        )

        remove_old_keyboard(tg_id)

        send_message(
            tg_id,
            "🛡 <b>Службовий бот охорони</b>\n\n"
            "Режим адміністратора.\n"
            "Версія: <b>v0.10</b>\n"
            "🧪 Тимчасове сховище без PostgreSQL.",
            admin_inline_menu()
        )
        return

    user = get_user(tg_id)

    if not user or user.get("status") != "active":
        remove_old_keyboard(tg_id)

        send_message(
            tg_id,
            "🛡 <b>Службовий бот охорони</b>\n\n"
            "Доступ закритий.\n"
            "Подай заявку один раз — після погодження повторна реєстрація не потрібна.",
            unauthorized_menu()
        )
        return

    remember_username(tg_id, username)
    user = get_user(tg_id) or {}

    remove_old_keyboard(tg_id)

    send_message(
        tg_id,
        "🛡 <b>Службовий бот охорони</b>\n\n"
        f"🏢 {escape(user.get('site') or '—')}\n"
        f"💼 {escape(user.get('position') or ROLE_TO_POSITION.get(user.get('role'),'—'))}\n\n"
        "Обери потрібний розділ:",
        main_inline_menu(user.get("role"))
    )

def handle_text(msg):
    tg_id = msg["from"]["id"]
    username = msg["from"].get("username")
    text = (msg.get("text") or "").strip()

    if text == "/start":
        handle_start(msg)
        return

    remember_username(tg_id, username)

    state, payload = get_state(tg_id)

    if state == "quiz":
        send_message(
            tg_id,
            "🎓 Тест уже триває. Відповідай кнопками під питанням."
        )
        return

    # ---------- OBJECT SEARCH ----------
    if state == "object_search":
        results = search_objects(text)

        if not results:
            send_message(
                tg_id,
                "🔎 Нічого не знайдено.\n"
                "Спробуй: <b>ворота</b>, <b>автоваг</b>, "
                "<b>СВС</b>, <b>генератор</b>, <b>ВТЛ</b>.",
                inline([[
                    {"text":"⬅️ До об’єктів","callback_data":"objects:site:1"}
                ]])
            )
        else:
            blocks = [f"🔎 <b>Знайдено: {len(results)}</b>"]
            for obj in results:
                blocks.append(object_card(obj))

            send_message(
                tg_id,
                "\n\n".join(blocks)[:4000],
                inline([[
                    {"text":"⬅️ До об’єктів","callback_data":"objects:site:1"}
                ]])
            )

        clear_state(tg_id)
        return

    # ---------- MANUAL SHIFT NAMES ----------
    if state == "shift_manual_post1":
        if len(text) < 5:
            send_message(tg_id, "Введи повне ПІБ.")
            return
        payload["post1_name"] = text
        payload["post1_tg_id"] = find_linked_tg_id(text, payload.get("site"))
        if payload.get("site") in SHIFT_SINGLE_POST_SITES:
            set_state(tg_id, "shift_change_presence", payload)
            send_message(tg_id, "🟢 <b>Розпочати зміну</b>\n\n5. Вкажи, чи є зміна персоналу:", shift_change_presence_keyboard())
            return
        set_state(tg_id, "shift_post2", payload)
        kb, _ = shift_member_keyboard(payload.get("site"), 2, exclude_name=text)
        send_message(
            tg_id,
            "🟢 <b>Розпочати зміну</b>\n\n"
            f"1️⃣ Пост №1: {escape(text)}\n\n"
            "4. Обери або введи ПІБ <b>Поста №2</b>:",
            kb
        )
        return

    if state == "shift_manual_post2":
        if len(text) < 5:
            send_message(tg_id, "Введи повне ПІБ.")
            return
        payload["post2_name"] = text
        payload["post2_tg_id"] = find_linked_tg_id(text, payload.get("site"))
        set_state(tg_id, "shift_change_presence", payload)
        send_message(tg_id, "🟢 <b>Розпочати зміну</b>\n\n5. Вкажи, чи є зміна персоналу:", shift_change_presence_keyboard())
        return

    if state == "shift_manual_master":
        if len(text) < 5:
            send_message(tg_id, "Введи повне ПІБ майстра.")
            return
        payload["master"] = text
        payload["activities"] = []
        set_state(tg_id, "shift_activities", payload)
        send_message(
            tg_id,
            "🚚 <b>Роботи на зміні</b>\n\n7. Обери один або декілька варіантів. Мінімум один:",
            shift_activities_keyboard([])
        )
        return

    # ---------- ADMIN: SOS PHONE CONTACTS ----------
    if tg_id == ADMIN_ID and state == "admin_sos_name":
        if len(text) < 2:
            send_message(tg_id, "Введи ПІБ або назву контакту.")
            return
        payload["name"] = text
        set_state(tg_id, "admin_sos_phone", payload)
        send_message(tg_id, "📞 Введи номер телефону, наприклад <code>+380501234567</code>:")
        return

    if tg_id == ADMIN_ID and state == "admin_sos_phone":
        phone = re.sub(r"[^0-9+]", "", text)
        if len(re.sub(r"\D", "", phone)) < 9:
            send_message(tg_id, "Номер виглядає закоротким. Введи ще раз.")
            return
        d = load_data(); d.setdefault("sos_phone_contacts", []).append({"name":payload.get("name"),"phone":phone,"created_at":utc_now_iso()}); save_data(d)
        clear_state(tg_id)
        send_message(tg_id, "✅ SOS-контакт додано.", admin_inline_menu())
        return

    # ---------- ADMIN: LEADERSHIP ----------
    if tg_id == ADMIN_ID and state == "admin_leader_name":
        if len(text) < 5:
            send_message(tg_id, "Введи повне ПІБ.")
            return
        payload["full_name"] = text
        set_state(tg_id, "admin_leader_position", payload)
        send_message(tg_id, "💼 Введи посаду:")
        return

    if tg_id == ADMIN_ID and state == "admin_leader_position":
        if len(text) < 2:
            send_message(tg_id, "Введи посаду.")
            return
        payload["position"] = text
        set_state(tg_id, "admin_leader_phone", payload)
        send_message(tg_id, "📞 Введи номер телефону:")
        return

    if tg_id == ADMIN_ID and state == "admin_leader_phone":
        payload["phone"] = text
        set_state(tg_id, "admin_leader_photo_choice", payload)
        send_message(tg_id, "📷 Додати фото керівника?", inline([[{"text":"📷 Додати фото","callback_data":"admin:leader:photo:add"}],[{"text":"➡️ Без фото","callback_data":"admin:leader:photo:skip"}]]))
        return

    # ---------- EVENT FLOW ----------
    if state == "event_place":
        if len(text) < 2:
            send_message(tg_id, "Вкажи місце або об’єкт.")
            return

        payload["place"] = text
        set_state(tg_id, "event_description", payload)

        send_message(
            tg_id,
            "🚨 <b>Подія</b>\n\n"
            f"📍 {escape(text)}\n\n"
            "Коротко опиши, <b>що сталося і які дії виконані</b>."
        )
        return

    if state == "event_description":
        if len(text) < 5:
            send_message(tg_id, "Опиши подію трохи детальніше.")
            return

        row = create_event(
            tg_id,
            payload["category"],
            payload["place"],
            text
        )

        clear_state(tg_id)

        send_message(
            tg_id,
            event_saved_text(row),
            shift_menu()
        )

        admin_text = (
            "🚨 <b>Нова подія</b>\n\n"
            + event_saved_text(row)
            + f"\n\n🏢 {escape(row.get('site') or '—')}\n"
            + f"👤 {escape(row.get('full_name') or '@'+str(row.get('username') or '—'))}"
        )

        if row.get("critical"):
            admin_text = "🔴 <b>КРИТИЧНА ПОДІЯ</b>\n\n" + admin_text

        send_message(ADMIN_ID, admin_text)
        return

    # ---------- DEFECT FLOW ----------
    if state == "defect_place":
        if len(text) < 2:
            send_message(tg_id, "Вкажи об’єкт або місце.")
            return

        payload["place"] = text
        set_state(tg_id, "defect_description", payload)

        send_message(
            tg_id,
            "⚠️ <b>Недолік</b>\n\n"
            f"📍 {escape(text)}\n\n"
            "Коротко опиши, <b>що саме несправне / пошкоджене</b>."
        )
        return

    if state == "defect_description":
        if len(text) < 5:
            send_message(tg_id, "Опиши недолік трохи детальніше.")
            return

        payload["description"] = text
        set_state(tg_id, "defect_photo_choice", payload)

        send_message(
            tg_id,
            "⚠️ <b>Недолік</b>\n\n"
            "Фото можна додати за бажанням.",
            inline([
                [{"text":"📷 Додати фото","callback_data":"defect:photo:add"}],
                [{"text":"➡️ Без фото","callback_data":"defect:photo:skip"}],
            ])
        )
        return

    user = get_user(tg_id)

    if not user or user.get("status") != "active":
        send_message(
            tg_id,
            "🔐 Доступ не надано.",
            unauthorized_menu()
        )
        return

    send_message(
        tg_id,
        "Оберіть дію кнопками меню.",
        admin_inline_menu() if tg_id == ADMIN_ID else main_inline_menu(user.get("role"))
    )

