# WEB
# =========================================================

def handle_photo(msg):
    tg_id = msg["from"]["id"]
    state, payload = get_state(tg_id)

    if tg_id == ADMIN_ID and state == "admin_leader_photo":
        photos = msg.get("photo") or []
        if not photos:
            return
        save_leadership_custom(payload, photos[-1]["file_id"])
        clear_state(tg_id)
        send_message(tg_id, "✅ Керівника з фото додано.", admin_inline_menu())
        return

    if state != "defect_photo":
        send_message(
            tg_id,
            "📷 Фото отримано, але зараз бот не очікує фото."
        )
        return

    photos = msg.get("photo") or []
    if not photos:
        return

    # Telegram передає кілька розмірів одного фото; останній — найбільший.
    file_id = photos[-1]["file_id"]
    payload["photo_file_id"] = file_id

    set_state(tg_id, "defect_priority", payload)

    send_message(
        tg_id,
        "✅ Фото додано.\n\n"
        "Тепер обери пріоритет недоліку:",
        defect_priority_keyboard()
    )


