@app.post(WEBHOOK_PATH)
def telegram_webhook():
    update = request.get_json(silent=True) or {}

    try:
        if "callback_query" in update:
            handle_callback(update["callback_query"])

        elif "message" in update:
            msg = update["message"]

            if msg.get("photo"):
                handle_photo(msg)
            elif "text" in msg:
                handle_text(msg)

    except Exception:
        log.exception("Webhook processing error")

    return jsonify({"ok": True})

def set_webhook():
    if not PUBLIC_URL:
        log.warning("PUBLIC_URL не задано")
        return

    result = tg(
        "setWebhook",
        {"url": f"{PUBLIC_URL}{WEBHOOK_PATH}"}
    )
    log.info("setWebhook: %s", result)

    commands_result = tg(
        "setMyCommands",
        {
            "commands": [
                {
                    "command": "start",
                    "description": "Запуск / головне меню"
                }
            ]
        }
    )
    log.info("setMyCommands: %s", commands_result)

    menu_result = tg(
        "setChatMenuButton",
        {
            "menu_button": {
                "type": "commands"
            }
        }
    )
    log.info("setChatMenuButton: %s", menu_result)



if __name__ == "__main__":
    init_postgres_storage()
    set_webhook()

    scheduler_thread = threading.Thread(
        target=scheduler_loop,
        name="security-scheduler",
        daemon=True
    )
    scheduler_thread.start()

    port = int(os.getenv("PORT", "10000"))

    log.info(
        "Starting Security Guard Bot v0.10 on port %s",
        port
    )

    app.run(
        host="0.0.0.0",
        port=port
    )
